/**
 * Jinx Lil' Monsta + Marionette: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lil%27_Monsta
 * Wiki: https://wiki.bloodontheclocktower.com/Marionette
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { setupReminders } from '#lib/core/rules/setup-reminders.ts';
import { scenario } from '#lib/core/testing/scenario.ts';

describe("Lil' Monsta + Marionette jinx", () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lilmonsta', 'marionette');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lilmonsta')?.name).toBe("Lil' Monsta");
		expect(data.byId.get('marionette')?.name).toBe('Marionette');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lilmonsta', 'marionette'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lilmonsta'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['marionette'])).not.toContain(jinx);
	});

	// The draw left the Marionette's token to place: it had no tile in the bag.
	const withBag = (s: ReturnType<typeof scenario>) =>
		s.do({
			type: 'BuildBag',
			tiles: [],
			includeTravellers: false,
			unseated: [{ characterId: 'marionette', label: 'Is The Marionette' }]
		});
	const marionetteAsk = (s: ReturnType<typeof scenario>) =>
		setupReminders(s.game, s.characters).find((r) => r.characterId === 'marionette');
	// The Marionette enters play once a Minion babysits Lil' Monsta, as their neighbour (M22).
	it('asks for no Marionette until someone babysits Lil\u2019 Monsta', () => {
		const s = withBag(scenario(['poisoner', 'chef', 'empath', 'monk', 'saint']));
		expect(marionetteAsk(s)).toBeUndefined();
		const later = s.reminder('poisoner', 'lilmonsta', 'Is The Demon');
		expect(marionetteAsk(later)?.candidates.sort()).toEqual(
			[later.seat('chef'), later.seat('saint')].sort()
		);
	});
});
